   364→
   365→            File sauceConnectLogFile = new File(logfile);
   366→            if (sauceConnectLogFile.exists()) {
   367→                return sauceConnectLogFile;
   368→            } else {
   369→                return null;
   370→            }
   371→        }
   372→
   373→        //otherwise, try to work out location
   374→        String fileName = "sc.log";
   375→        File logFileDirectory = new File(OperatingSystem.getOperatingSystem().getDefaultSauceConnectLogDirectory());
   376→
   377→        //has --tunnel-name been specified?
